films.V135StopMetres:
// v135-stop-metres, the signature: two stops side by side on one metre scale. Two lanes on the paper, the left one the
// stop from 50 km/h, the right one from 100 (the film's one data hue); both bars run up the scale together, the left one
// lands at 14 m and stops, the right one keeps running to 56 m. The "child" shot first draws the dashed line at 40 m where
// someone steps out, rings it, and only then lets the two stops run: the left lands under the line, the right runs past it.
// Figures: Queensland Government stopping-distance table, dry road (the spec's source line).
import React from 'react';
import {useCurrentFrame} from 'remotion';
import {cueFrame, entrance, Haptic, Land, lead, PictureBand, Sfx} from '../common';
import {C, rgba} from '../../tokens';
import {ease, prog} from '../../lib/anim';
import {CameraLayer, Hud} from '../../lib/camera';
import {OBJ} from '../../lib/layer';
import type {SceneCtx} from '../../types';
import {Ink} from '../kit/ink';
import {FitText, Quiet, RollDigits, S} from '../kit/p2';

type Lane = {label: string; value: number};
type P = {
  shot?: 'race' | 'child';
  title?: string;
  a?: Lane;
  b?: Lane;
  line?: number;
  lineLabel?: string;
  at?: number | string;
  lineAt?: number | string;
  source?: string;
  /** which lanes print their figure when they land (the race shows only who stops first) */
  showA?: boolean;
  showB?: boolean;
};

const Y0 = 1210; // 0 m
const K = 11; // px a metre: 60 m reaches y 550
const BAR_W = 150;
const AX = 340; // lane a's left
const BX = 590; // lane b's left
const RATE = 1.3; // metres a frame: both stops run at one speed, so the short one lands first

const yOf = (m: number) => Y0 - m * K;

export const V135StopMetres: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const e = entrance(ctx);
  const base = lead(ctx);
  const a = p.a ?? {label: '', value: 14};
  const b = p.b ?? {label: '', value: 56};
  const child = p.shot === 'child';
  const lineM = p.line ?? 40;
  const lineAt = Math.min(e, cueFrame(ctx, p.lineAt ?? 0));
  const go = child ? Math.max(base + 2, lineAt + 10) : Math.max(base + 6, cueFrame(ctx, p.at ?? 0) + 6);
  const landA = go + Math.round(a.value / RATE);
  const landB = go + Math.round(b.value / RATE);
  const run = (v: number) => Math.min(v, Math.max(0, (frame - go) * RATE) * (0.6 + 0.4 * ease.enter(prog(frame, go, 10))));
  const hA = run(a.value) * K;
  const hB = run(b.value) * K;
  const show = prog(frame, e, 10, ease.enter);
  const lineK = child ? 0.35 + 0.65 * prog(frame, lineAt, 10, ease.enter) : 0;
  const ticks = [0, 20, 40];
  const lanes = [
    {x: AX, h: hA, lane: a, land: landA, color: rgba(C.ink, 0.16), figure: p.showA === true},
    {x: BX, h: hB, lane: b, land: landB, color: rgba(C.ink, 0.42), figure: p.showB === true},
  ];
  return (
    <PictureBand camera={false}>
      <CameraLayer depth={0.6}>
        {ticks.map((m) => (
          <div key={m} style={{position: 'absolute', left: 250, width: 500, top: yOf(m) - 2, height: 4, backgroundColor: C.rule, opacity: show}} />
        ))}
      </CameraLayer>
      <CameraLayer depth={1}>
        {lanes.map((l, i) => (
          <div key={i} className={OBJ} style={{position: 'absolute', left: l.x, width: BAR_W, top: Y0 - Math.max(6, l.h), height: Math.max(6, l.h), backgroundColor: l.color, border: `3px solid ${C.ink}`, borderBottom: 'none', borderRadius: '14px 14px 0 0', opacity: show}} />
        ))}
        {child ? (
          <div style={{position: 'absolute', left: 250, width: 500 * lineK, top: yOf(lineM) - 3, height: 0, borderTop: `6px dashed ${C.ink}`}} />
        ) : null}
      </CameraLayer>
      <Hud>
        {/* one composited layer: the words keep a plain grey anti-aliasing, never a coloured subpixel fringe */}
        <div style={{position: 'absolute', left: 0, top: 0, width: 1080, height: 1920, willChange: 'transform', opacity: 0.999}}>
        {p.title ? <FitText text={p.title} x={S.left} y={410} size={64} min={44} maxLines={1} at={e} /> : null}
        {ticks
          .filter((m) => !(child && m === lineM))
          .map((m) => (
            <FitText key={m} text={`${m}`} x={150} y={yOf(m) - 22} w={80} size={40} min={36} maxLines={1} weight={600} at={e} latin />
          ))}
        {lanes.map((l, i) => (
          <React.Fragment key={i}>
            <FitText text={l.lane.label} x={l.x + BAR_W / 2} y={Y0 + 18} w={240} size={44} min={34} maxLines={1} align="center" at={e} />
            {l.figure && frame >= l.land - 2 ? (
              <div style={{position: 'absolute', left: l.x - 20, width: BAR_W + 40, top: Y0 - l.lane.value * K - 104, display: 'flex', justifyContent: 'center', alignItems: 'baseline', gap: 8}}>
                <RollDigits text={`${l.lane.value}`} at={l.land - 2} size={84} dur={10} t="ink" />
              </div>
            ) : null}
          </React.Fragment>
        ))}
        {child ? <FitText text={p.lineLabel ?? `${lineM}`} x={780} y={yOf(lineM) - 62} w={110} size={110} min={80} maxLines={1} anim="none" /> : null}
        {child ? (
          <Ink
            marks={[
              {kind: 'underline', box: {x: 780, y: yOf(lineM) - 62, w: 120, h: 118}, at: lineAt + 8},
              {kind: 'tick', box: {x: AX + BAR_W + 14, y: yOf(a.value) - 70, w: 60, h: 60}, at: landA + 6},
            ]}
            end={ctx.dur}
          />
        ) : null}
        {p.source ? <Quiet text={p.source} x={S.left} y={Y0 + 92} w={S.right - S.left} at={e + 6} /> : null}
        </div>
      </Hud>
      {child ? <Sfx name="asmr-tick-fine" at={lineAt} volume={0.3} /> : null}
      <Sfx name="asmr-count-roll" at={go} volume={0.28} />
      <Land at={landA} />
      <Haptic kind="light" at={landA} volume={0.22} />
      <Land at={landB} />
      <Haptic kind="rigid" at={landB + 1} volume={0.28} />
    </PictureBand>
  );
};

films.V135StopMetresHook:
// v135-stop-metres, the hook: the light at night, a horn, and frame 0 already reads my speed and the metres my stop takes.
// Paper and ink: the claim (my speed) big on the paper, the stop's metres counting up beside its quiet label, and under them
// the night avenue as a greyscale plate that drifts in slowly. The act-1 grade greys and dims it; the horn is the spec's.
import React from 'react';
import {Img, staticFile, useCurrentFrame} from 'remotion';
import {cueFrame, Haptic, lead, PictureBand, Sfx} from '../common';
import {C} from '../../tokens';
import {ease, prog} from '../../lib/anim';
import {CameraLayer, Hud} from '../../lib/camera';
import type {SceneCtx} from '../../types';
import {Card, FitText, Quiet, RollDigits, S} from '../kit/p2';

type P = {claim?: string; label?: string; metres?: string; unit?: string; countAt?: number | string};

const PLATE_Y = 860;
const PLATE_H = 480;

export const V135StopMetresHook: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const base = lead(ctx);
  const count = Math.max(base + 10, cueFrame(ctx, p.countAt ?? '0.4s'));
  const w = S.right - S.left;
  const push = 1.04 + 0.08 * ease.drift(prog(frame, 0, Math.max(1, ctx.dur)));
  const rise = prog(frame, 0, 10, ease.enter);
  return (
    <PictureBand camera={false}>
      <CameraLayer depth={0.6}>
        <Card x={S.left} y={p.metres ? PLATE_Y : 680} w={w} h={p.metres ? PLATE_H : 660} r={30}>
          <Img
            src={staticFile('photos/traffic-light-trails-portrait.jpg')}
            style={{position: 'absolute', left: 0, top: 0, width: '100%', height: '100%', objectFit: 'cover', objectPosition: '50% 62%', filter: 'grayscale(1) contrast(1.08)', transform: `scale(${push.toFixed(4)})`, transformOrigin: '50% 60%'}}
          />
        </Card>
      </CameraLayer>
      <Hud>
        <FitText text={p.claim ?? ''} x={S.left} y={420} w={w} size={200} min={120} maxLines={1} anim="none" />
        {p.metres ? (
          <>
            <Quiet text={p.label ?? ''} x={S.left} y={700} w={300} at={0} />
            <div style={{position: 'absolute', left: S.left + 300, top: 640, display: 'flex', alignItems: 'baseline', gap: 18, opacity: 0.4 + 0.6 * rise, color: C.ink}}>
              <RollDigits text={p.metres} at={count} size={130} dur={34} t="accent" />
            </div>
            <Quiet text={p.unit ?? ''} x={S.left + 520} y={700} w={120} at={count} />
          </>
        ) : null}
      </Hud>
      <Sfx name="asmr-count-roll" at={count} volume={0.32} />
      <Haptic kind="light" at={count + 34} volume={0.22} />
    </PictureBand>
  );
};
